public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();
    int[] X = new int[M];
    for (int i = 0; i < M; i++) {
        X[i] = sc.nextInt();
    }

    long[] cost = new long[N];
    for (int i = 0; i < M - 1; i++) {
        int from = X[i] - 1;
        int to = X[i + 1] - 1;
        if (from > to) {
            to += N;
        }
        cost[from]++;
        cost[to]--;
    }

    for (int i = 1; i < N; i++) {
        cost[i] += cost[i - 1];
    }

    long totalCost = 0;
    for (int i = 0; i < M - 1; i++) {
        int from = X[i] - 1;
        int to = X[i + 1] - 1;
        if (from > to) {
            totalCost += to + N - from;
        } else {
            totalCost += to - from;
        }
    }

    long maxReduction = 0;
    for (int i = 0; i < N; i++) {
        maxReduction = Math.max(maxReduction, cost[i]);
    }

    long answer = totalCost - maxReduction;
    System.out.println(answer);
}
